const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Cart = () => {
  const [count, setCount] = useState(0);

  return (
    <div>
      <p className="cart">담은 것 {count}개</p>
      <article className="card">
        <h3 className="card__title">오버사이즈 셔츠</h3>
        <p className="card__price">189,000원</p>
        <button className="pick" type="button" onClick={() => setCount(count + 1)}>담기</button>
        <button className="clear" type="button" onClick={() => setCount(0)}>비우기</button>
      </article>
    </div>
  );
};

root.render(<Cart />);
